using System.Diagnostics; namespace NXT.Core; public sealed class VmManager { Process? process; public void Start(string runtime){if(process is {HasExited:false})return;var exe=Path.Combine(runtime,"qemu","qemu-system-x86_64.exe");var disk=Path.Combine(runtime,"android","android.qcow2");if(!File.Exists(exe)||!File.Exists(disk))throw new FileNotFoundException("Download a compatible QEMU runtime and bootable Android QCOW2 image. This starter installer does not include these files.");var info=new ProcessStartInfo(exe){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(exe)!};foreach(var a in new[]{"-machine","q35,accel=whpx","-cpu","max","-smp","2","-m","3072","-drive",$"file={disk},format=qcow2,if=virtio","-device","virtio-vga","-display","sdl","-device","qemu-xhci","-device","usb-tablet","-netdev","user,id=n0","-device","virtio-net-pci,netdev=n0"})info.ArgumentList.Add(a);process=Process.Start(info)??throw new InvalidOperationException("Unable to launch QEMU");}public void Stop(){if(process is {HasExited:false}){process.Kill(true);process.WaitForExit();}process?.Dispose();process=null;}}